189		srcPath := "testdata/db-and-wals/wal-01"
190		walName := "00000000000000000001.wal"
191	
192		// Create a directory containing the WAL file (mimics what the store does).
193		walDir := filepath.Join(t.TempDir(), "wal-dir")
194		if err := os.Mkdir(walDir, 0755); err != nil {
195			t.Fatalf("unexpected error creating WAL dir: %s", err.Error())
