type SyncState bool

var (
	// Sync indicates the file should be synced after writing.
	Sync SyncState = true
	// NoSync indicates the file should not be synced after writing.
	NoSync SyncState = false
)

// WriteCRC32SumFile writes the given CRC32 checksum to path as an 8-character
// lowercase hex string (e.g. "1a2b3c4d"). If sync is Sync, the file is fsynced
// to disk before returning.
func WriteCRC32SumFile(path string, sum uint32, sync SyncState) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
	if err != nil {
		return err
	}
	defer f.Close()

	if _, err := f.Write([]byte(fmt.Sprintf("%08x", sum))); err != nil {
		return err
	}
	if sync {
		if err := f.Sync(); err != nil {
			return err
		}
	}
	return f.Close()
}

