// compares it to the expected checksum read from crcPath. It returns (true, nil)
// if they match, (false, nil) if they do not match, or (false, error) if either
// file cannot be read or does not exist.
func CompareCRC32SumFile(dataPath, crcPath string) (bool, error) {
	expected, err := ReadCRC32SumFile(crcPath)
	if err != nil {
		return false, err
	}
	actual, err := CRC32(dataPath)
	if err != nil {
		return false, err
	}
	return actual == expected, nil
